-- RS3 API Probe (generated by the RS3 Plugin API extension for VS Code, definitions v{{VERSION}})
--
-- Read-only checks of the plugin API against the extension's definitions, for the beta/dev client.
-- It looks names up and briefly creates one hidden component of each UI type (then destroys them).
-- It does not move items, click, or automate anything.
--
-- Results go to VS Code over HTTP (run "RS3: Start Probe Receiver"). The console commands take the
-- plugin's folder name:   pon rs3_api_probe   ppr rs3_api_probe   ppe rs3_api_probe httpAccess   prl rs3_api_probe
-- Without HTTP it prints RS3P|… lines to the console; copy them and run
-- "RS3: Import Probe Output" in VS Code.
--
-- Open the ribbon icon and the settings icon once while it runs to measure those windows.

-- Options -------------------------------------------------------------------------------
-- Some component types are created bare (no content) and read straight away. These ones are
-- more likely to misbehave like that, so they're skipped unless you set this to true.
local INCLUDE_RISKY = false
-- If a run crashes the client, the next run skips whatever it was doing. Set this to true once
-- to try those steps again.
local RESET_SKIPS = false
------------------------------------------------------------------------------------------

local EXPECTED = {{EXPECTED}}

local RUN = tostring(math.random(100000, 999999))
local R = {
  probe = "rs3", run = RUN, version = "{{VERSION}}", kind = "report",
  meta = { lua = _VERSION },
  counts = { ok = 0, missing = 0, wrongType = 0, error = 0 },
  missing = {}, wrongType = {}, errors = {}, values = {},
  instances = {}, extra = {}, extraGlobals = {}, ids = {},
  styles = { keys = {}, sheets = {} }, notes = {}
}

---------------------------------------------------------------- helpers
local function note(msg) R.notes[#R.notes + 1] = tostring(msg) end

local function get(path)
  local cur = _G
  for part in path:gmatch("[^.:]+") do
    if cur == nil then return nil, "parent is nil" end
    local ok, v = pcall(function() return cur[part] end)
    if not ok then return nil, tostring(v) end
    cur = v
  end
  return cur
end

local function simple(v)
  local t = type(v)
  if t == "number" or t == "boolean" then return v end
  if t == "string" then
    if #v > 80 then return v:sub(1, 80) .. "…" end
    return v
  end
  return nil
end

local KIND_OK = {
  f = { ["function"] = true },
  n = { number = true },
  t = { table = true, userdata = true },
}
local function check(path, kind, docValue)
  local v, err = get(path)
  if err then R.counts.error = R.counts.error + 1; R.errors[path] = err; return end
  if v == nil then R.counts.missing = R.counts.missing + 1; R.missing[#R.missing + 1] = path; return end
  local t = type(v)
  if KIND_OK[kind] and not KIND_OK[kind][t] then
    R.counts.wrongType = R.counts.wrongType + 1
    R.wrongType[path] = t
  else
    R.counts.ok = R.counts.ok + 1
  end
  local s = simple(v)
  if s ~= nil and not (docValue ~= nil and s == docValue) then R.values[path] = s end
end

local function keysOf(obj, limit)
  local out, seen = {}, {}
  local function add(k)
    if type(k) == "string" and not seen[k] and k:sub(1, 2) ~= "__" then
      seen[k] = true
      out[#out + 1] = k
    end
  end
  local function scan(t)
    if type(t) ~= "table" then return end
    local ok, f, s, c = pcall(pairs, t)
    if not ok then return end
    pcall(function() for k in f, s, c do add(k); if #out >= (limit or 400) then break end end end)
  end
  scan(obj)
  local okm, mt = pcall(getmetatable, obj)
  if okm and type(mt) == "table" then
    scan(mt)
    if type(rawget(mt, "__index")) == "table" then scan(rawget(mt, "__index")) end
  end
  return out
end

---------------------------------------------------------------- JSON
local function enc(v, depth)
  depth = depth or 0
  local t = type(v)
  if t == "nil" then return "null" end
  if t == "boolean" then return v and "true" or "false" end
  if t == "number" then
    if v ~= v or v == math.huge or v == -math.huge then return "null" end
    return math.type(v) == "integer" and tostring(v) or string.format("%.6g", v)
  end
  if t == "string" then
    return '"' .. v:gsub('[%c"\\]', function(ch)
      local m = { ['"'] = '\\"', ['\\'] = '\\\\', ['\n'] = '\\n', ['\r'] = '\\r', ['\t'] = '\\t' }
      return m[ch] or string.format("\\u%04x", ch:byte())
    end) .. '"'
  end
  if t ~= "table" or depth > 8 then return '"<' .. t .. '>"' end
  local n = #v
  local parts = {}
  if n > 0 then
    for i = 1, n do parts[i] = enc(v[i], depth + 1) end
    return "[" .. table.concat(parts, ",") .. "]"
  end
  for k, val in pairs(v) do parts[#parts + 1] = enc(tostring(k)) .. ":" .. enc(val, depth + 1) end
  return "{" .. table.concat(parts, ",") .. "}"
end

---------------------------------------------------------------- status window
local status = {}
local function setStatus(lines)
  if not status.text then return end
  pcall(function() status.text.content = table.concat(lines, "\n") end)
end
local function makeWindow(root)
  pcall(function()
    local box = ui.GroupBox.new(root)
    box.stylesheetID = id.StyleSheet.DEFAULT
    box:SetSize(420, 190)
    box:SetPos(0, 0, 0.5, 0.15, -0.5, 0)
    pcall(function() box.headerText.content = "RS3 API Probe" end)
    local t = ui.Text.new(box)
    t.font = id.Font.MUSEO_SANS_15PT_REGULAR
    t:SetPos(14, 34); t:SetSize(-28, -84, 1, 1)
    t.content = "Starting…"
    local b = ui.Button.new(box)
    b.stylesheetID = id.StyleSheet.BUTTON_DEFAULT
    b.label = "Close"
    b:SetSize(110, 32); b:SetPos(0, -12, 0.5, 1, -0.5, -1)
    b:Subscribe(ui.Hook.ONBUTTONPRESSED, function() pcall(function() box:Destroy() end); status.text = nil end)
    status.box, status.text = box, t
  end)
end

---------------------------------------------------------------- sending results
local sentVia = "pending"
-- console fallback: long lines, a few per tick so the client doesn't stall
local outQueue = {}
local function logChunks(json, tag)
  local CHUNK = 800
  local n = math.ceil(#json / CHUNK)
  outQueue[#outQueue + 1] = formatStr("RS3P-BEGIN|{}|{}|{}", RUN, tag, n)
  for i = 1, n do
    outQueue[#outQueue + 1] = "RS3P|" .. RUN .. "|" .. tag .. "|" .. i .. "/" .. n .. "|" .. json:sub((i - 1) * CHUNK + 1, i * CHUNK)
  end
  outQueue[#outQueue + 1] = formatStr("RS3P-END|{}|{}", RUN, tag)
end
pcall(function()
  Event.Logic.Subscribe("rs3probe_out", function()
    for _ = 1, 20 do
      if #outQueue == 0 then return end
      log(table.remove(outQueue, 1))
    end
  end)
end)
local function send(payload, tag, done)
  local json = enc(payload)
  local canHttp = false
  pcall(function()
    canHttp = Plugin.urls ~= nil and Plugin.urls.probe ~= nil and Plugin.HasPermission(PluginPermissions.httpAccess)
  end)
  if canHttp then
    local ok = pcall(function()
      -- the client appends the path to the base URL as-is; without the "/" the port becomes "47321report"
      local req = HTTPRequest.new(Plugin.urls.probe, "/report")
      req:AddHeader("Content-Type", "application/json")
      req:Post(json, function(r)
        if r.successful then done("Sent to VS Code.")
        else
          logChunks(json, tag)
          done("VS Code didn't answer (" .. tostring(r.responseCode) .. " " .. tostring(r.errorInfo) .. "). Printed RS3P lines to the console instead.")
        end
      end)
    end)
    if ok then return end
  end
  logChunks(json, tag)
  done("Printed RS3P lines to the console (no httpAccess). Copy them into VS Code.")
end

---------------------------------------------------------------- the checks, run a few per tick
local queue = {}
local function push(fn) queue[#queue + 1] = fn end
local total = 0

local root
pcall(function() root = ui.Interfaces:GetComponent(id.Component.TOPLEVEL_V2__PLUGIN_BUILD_LAYER_TOP) end)
if root then
  makeWindow(root)
  pcall(function() R.meta.screen = { w = root.width, h = root.height } end)
else note("could not get the plugin build layer") end

-- 1. names reachable from globals
for _, e in ipairs(EXPECTED.statics) do push(function() check(e[1], e[2], e[3]) end) end

-- 2. objects (phase 2): one at a time, with crash breadcrumbs; see the driver below
local RISKY = { Model = true, ModelGroup = true, Canvas = true, CutsceneLayer = true, RadialProgressOverlay = true,
  PagedLayer = true, PagedCarousel = true, Carousel = true }
local BC_KEY, SKIP_KEY = "rs3probe.step", "rs3probe.skip"
local skip = {}
local function saveSkips()
  local names = {}
  for k in pairs(skip) do names[#names + 1] = k end
  pcall(function() PersistentDB:SetString(SKIP_KEY, table.concat(names, ",")) end)
end
pcall(function()
  if RESET_SKIPS then PersistentDB:SetString(SKIP_KEY, ""); PersistentDB:SetString(BC_KEY, ""); return end
  local s = PersistentDB:GetString(SKIP_KEY)
  if s then for n in s:gmatch("[^,]+") do skip[n] = true end end
  local last = PersistentDB:GetString(BC_KEY)
  if last and last ~= "" then
    local what = last:match("^%S+ (%S+)") or last
    note("The previous run stopped while " .. last .. ". Skipping " .. what .. " this time.")
    R.meta.crashedAt = last
    skip[what] = true
    saveSkips()
  end
end)
for k in pairs(skip) do note("skipped (crashed before): " .. k) end
local function breadcrumb(step)
  pcall(function() PersistentDB:SetString(BC_KEY, step or "") end)
  if step then log("RS3 API Probe: " .. step) end
end

-- Skip list: members that crash the client when read on a fresh component.
-- ui.Grid.cellHeight divides by zero inside the client (rs2client 951.1) on a grid with no columns/rows.
-- cellWidth is not tested yet; it is skipped too because it is very likely the same calculation.
local UNSAFE_MEMBERS = { ["ui.Grid"] = { cellHeight = true, cellWidth = true } }

local function inspect(cls, obj)
  local members = EXPECTED.instances[cls]
  if not members then return end
  local res = { members = {}, extra = {} }
  local known = {}
  local unsafe = UNSAFE_MEMBERS[cls] or {}
  for _, m in ipairs(members) do
    known[m[1]] = true
    if unsafe[m[1]] then
      res.members[m[1]] = { t = "skipped" }
      note("not read (crashes the client on a new component): " .. cls .. "." .. m[1])
      goto continue
    end
    local ok, v = pcall(function() return obj[m[1]] end)
    local t = ok and type(v) or "error"
    local rec = { t = t }
    if not ok then rec.err = tostring(v) end
    local sv = ok and simple(v)
    if sv ~= nil then rec.v = sv end
    if m[2] == "f" and t ~= "function" then rec.bad = true end
    if t == "nil" or t == "error" then rec.bad = true end
    res.members[m[1]] = rec
    ::continue::
  end
  for _, k in ipairs(keysOf(obj)) do if not known[k] then res.extra[#res.extra + 1] = k end end
  R.instances[cls] = res
end

-- each entry runs on its own tick
local objSteps = {}
local function valueSample(cls, make)
  if skip[cls] then return end
  objSteps[#objSteps + 1] = function()
    breadcrumb("reading " .. cls)
    local ok, v = pcall(make)
    if ok and v ~= nil then inspect(cls, v) else note("no sample for " .. cls .. ": " .. tostring(v)) end
    breadcrumb(nil)
  end
end
valueSample("Vector2", function() return Vector2.new(1, 2) end)
valueSample("Vector3", function() return Vector3.new(1, 2, 3) end)
valueSample("Vector4", function() return Vector4.new(1, 2, 3, 4) end)
valueSample("ui.Pos", function() return ui.Pos.new(1, 2) end)
valueSample("ui.Size", function() return ui.Size.new(1, 2) end)
valueSample("ui.Margin", function() return ui.Margin.new(1, 2, 3, 4) end)
valueSample("ui.StyleSheet", function() return ui.StyleSheets:Find(id.StyleSheet.BUTTON_DEFAULT) end)
valueSample("PlayerEntity", function() return Player.GetEntity() end)
for _, t in ipairs(EXPECTED.uiTypes) do
  local cls = "ui." .. t
  if skip[cls] then
    -- already noted
  elseif RISKY[t] and not INCLUDE_RISKY then
    note("not created (set INCLUDE_RISKY = true to include): " .. cls)
  elseif root then
    local made
    objSteps[#objSteps + 1] = function()
      breadcrumb("creating " .. cls)
      local ok, c = pcall(function() return ui[t].new(root) end)
      if ok and c ~= nil then
        made = c
        pcall(function() c.hidden = true end)
      else note("could not create " .. cls .. ": " .. tostring(c)) end
      breadcrumb(nil)
    end
    objSteps[#objSteps + 1] = function()
      if made == nil then return end
      breadcrumb("reading " .. cls)
      inspect(cls, made)
      if t == "Text" then inspect("ui.TextData", made) end
      if t == "Sprite" then inspect("ui.SpriteData", made) end
      breadcrumb("destroying " .. cls)
      local c = made
      made = nil
      pcall(function() c:Destroy() end)
      breadcrumb(nil)
    end
  end
end

-- 3. undocumented members of global tables, and undocumented globals
push(function()
  local expectedGlobal = {}
  for _, g in ipairs(EXPECTED.globals) do expectedGlobal[g] = true end
  local std = { "_G", "_VERSION", "assert", "collectgarbage", "coroutine", "debug", "dofile", "error", "getmetatable", "io", "ipairs",
    "load", "loadfile", "math", "next", "os", "package", "pairs", "pcall", "print", "rawequal", "rawget", "rawlen", "rawset",
    "require", "select", "setmetatable", "string", "table", "tonumber", "tostring", "type", "utf8", "warn", "xpcall", "PluginShutdown" }
  for _, s in ipairs(std) do expectedGlobal[s] = true end
  for _, k in ipairs(keysOf(_G, 2000)) do
    if not expectedGlobal[k] then
      local ok, v = pcall(function() return _G[k] end)
      R.extraGlobals[k] = ok and type(v) or "error"
    end
  end
  for g, members in pairs(EXPECTED.members) do
    local obj = get(g)
    if obj ~= nil then
      local known = {}
      for _, m in ipairs(members) do known[m] = true end
      local extra = {}
      for _, k in ipairs(keysOf(obj)) do if not known[k] then extra[#extra + 1] = k end end
      if #extra > 0 then R.extra[g] = extra end
    end
  end
end)

-- 4. id tables: the names the docs don't list
push(function()
  local okId = type(id) == "table" or type(id) == "userdata"
  if not okId then note("id is " .. type(id)); return end
  R.ids.tables = keysOf(id, 200)
  for _, t in ipairs({ "StyleSheet", "Font" }) do
    local tbl = get("id." .. t)
    if tbl ~= nil then
      local names = {}
      for _, k in ipairs(keysOf(tbl, 3000)) do
        local ok, v = pcall(function() return tbl[k] end)
        names[k] = ok and simple(v) or true
      end
      R.ids[t] = names
    end
  end
  local comp = get("id.Component")
  if comp ~= nil then R.ids.componentCount = #keysOf(comp, 100000) end
end)

-- 5. ui.StyleValue keys and built-in stylesheet values
-- Skip list: StyleSheet:GetValue crashes the client (access violation, rs2client 951.1) for property
-- keys of 2^31 and above, and ui.StyleValue has some. Only keys in 0..2^31-1 are read; the rest are
-- reported as keys but never passed to the client.
local function isSafeStyleKey(v) return math.type(v) == "integer" and v >= 0 and v < 0x80000000 end
local found = {}
push(function()
  local function walk(t, path, depth)
    if depth > 8 then return end
    local ok, f, s, c = pcall(pairs, t)
    if not ok then if path == "" then note("ui.StyleValue cannot be listed (" .. type(t) .. ")") end return end
    pcall(function()
      for k, v in f, s, c do
        local p = path == "" and tostring(k) or (path .. "." .. tostring(k))
        if type(v) == "number" then found[#found + 1] = { p, v }; R.styles.keys[p] = v
        elseif type(v) == "table" or type(v) == "userdata" then walk(v, p, depth + 1) end
      end
    end)
  end
  walk(ui.StyleValue, "", 0)
  local unsafe = {}
  for _, kv in ipairs(found) do if not isSafeStyleKey(kv[2]) then unsafe[#unsafe + 1] = kv[1] end end
  if #unsafe > 0 then note("not read with GetValue (key out of range, crashes the client): " .. table.concat(unsafe, ", ")) end
end)
for _, name in ipairs(EXPECTED.styleSheets) do
  push(function()
    local ok, sheet = pcall(function() return ui.StyleSheets:Find(id.StyleSheet[name]) end)
    if ok and sheet then
      local vals = {}
      for _, kv in ipairs(found) do
        if isSafeStyleKey(kv[2]) then
          local okV, v = pcall(function() return sheet:GetValue(kv[2]) end)
          if okV and v ~= nil then vals[kv[1]] = v end
        end
      end
      R.styles.sheets[name] = vals
    end
  end)
end

-- 6. window sizes: measured when you open the ribbon and settings windows
local layers = {}
local function measure(which)
  return function(e)
    pcall(function()
      local c = e.component
      layers[which] = { w = c.width, h = c.height, x = c.x, y = c.y }
      if root then layers.screen = { w = root.width, h = root.height } end
      send({ probe = "rs3", run = RUN, kind = "layers", layers = layers }, "layers", function(msg) note(msg) end)
      setStatus({ "Measured the " .. which .. " window: " .. tostring(c.width) .. " × " .. tostring(c.height), status.last or "" })
    end)
  end
end
pcall(function() Event.ContentLayerReady.Subscribe("rs3probe", measure("ribbon")) end)
pcall(function() Event.SettingsLayerReady.Subscribe("rs3probe", measure("settings")) end)

---------------------------------------------------------------- driver
-- phase 1: names (nothing created), results sent straight away
-- phase 2: objects, one per tick, results sent as a second payload
local phase, idx, oi, wait = 1, 1, 1, 0
local summary = ""
local function finishPhase1()
  R.meta.queued = total
  local c = R.counts
  summary = formatStr("Checked {} names: {} ok, {} missing, {} wrong type, {} errors.", c.ok + c.missing + c.wrongType + c.error, c.ok, c.missing, c.wrongType, c.error)
  log("RS3 API Probe: " .. summary)
  send(R, "report", function(msg)
    status.last = msg
    log("RS3 API Probe: names: " .. msg)
  end)
end
local function finishPhase2()
  breadcrumb(nil)
  local n = 0
  for _ in pairs(R.instances) do n = n + 1 end
  send({ probe = "rs3", run = RUN, kind = "objects", instances = R.instances, notes = R.notes, meta = R.meta }, "objects", function(msg)
    status.last = msg
    setStatus({ summary, formatStr("Checked {} object types. {}", n, msg), "", "Open the ribbon icon and the settings icon", "to measure those windows too." })
    log("RS3 API Probe: objects: " .. msg)
  end)
end

total = #queue
Event.Logic.Subscribe("rs3probe", function()
  if phase == 1 then
    local budget = 120
    while budget > 0 and idx <= #queue do
      local ok, err = pcall(queue[idx])
      if not ok then note("step " .. idx .. ": " .. tostring(err)) end
      idx = idx + 1
      budget = budget - 1
    end
    setStatus({ formatStr("Checking names… {} / {}", idx - 1, #queue) })
    if idx > #queue then
      finishPhase1()
      phase, wait = 2, 100 -- give the first result ~2 s to go out before touching objects
    end
  elseif phase == 2 then
    if wait > 0 then wait = wait - 1; return end
    if oi <= #objSteps then
      local step = objSteps[oi]
      oi = oi + 1
      local ok, err = pcall(step)
      if not ok then note("object step " .. (oi - 1) .. ": " .. tostring(err)); breadcrumb(nil) end
      setStatus({ summary, formatStr("Checking objects… {} / {}", oi - 1, #objSteps) })
    else
      finishPhase2()
      phase = 3
    end
  end
end)

function PluginShutdown()
  pcall(function() Event.Logic.Unsubscribe("rs3probe") end)
  pcall(function() Event.Logic.Unsubscribe("rs3probe_out") end)
  pcall(function() Event.ContentLayerReady.Unsubscribe("rs3probe") end)
  pcall(function() Event.SettingsLayerReady.Unsubscribe("rs3probe") end)
end
